/* Raw PCM for the shared-memory writer, generated by build_xnu.sh.
 * 48 kHz / 24-bit signed LE / stereo, exactly PCM_BYTES long (looped at
 * build time), copied to the DSP-visible low-DRAM page by the shim. */
	.section .rodata
	.align 3
	.global pcm_img
pcm_img:
	.incbin "pcm.raw"
	.global pcm_img_end
pcm_img_end:
